#!/bin/bash
# Acceptance test of ssw: align a 149-base query with a mismatch and a
# deletion to a 5 kb target (ssw_test, SAM output); the alignment, its score
# and the suboptimal score must be those of an x86_64 build.
set -uo pipefail
bin=$BENCH_SRC_DIR/ssw/src/ssw_test
[ -x "$bin" ] || { echo "error: the build left no src/ssw_test"; exit 1; }
work=$BENCH_CACHE_DIR/acceptance
rm -rf "$work" && mkdir -p "$work" && cd "$work"
cat > ref.fa <<'EOF'
>ref

EOF
cat > q.fa <<'EOF'
>q
CTAATGTCACCGACCTCTCGATTTGTTAGTGGTTCTATAGGGTGTAGGCACTGGCGGGTTCCATGGCGCCATACTACTAAGCGAGAGGAGTAAAACACTATGCGGGGACTTCATGCGAGCGACGAGGGAGCGGACAATCTGCGGCGTAA
EOF
got=$("$bin" -s -c ref.fa q.fa 2> ssw.log | grep -v '^@' | cut -f1-6,12-) || { cat ssw.log; echo "error: ssw_test failed"; exit 1; }
expected=$(printf 'q\t0\tref\t100\t5\t50=1X49=1D49=\tAS:i:291\tNM:i:2\tZS:i:218')
echo "$got"
[ "$got" = "$expected" ] || { echo "FAIL: the alignment differs from an x86_64 build's:"; echo "$expected"; exit 1; }
echo "PASS ssw"
